// Error types mirroring the public behavior of jsonschema.exceptions.

export class UndefinedTypeCheck extends Error {
  constructor(type) {
    super(`Type '${type}' is unknown to this type checker`);
    this.name = 'UndefinedTypeCheck';
    this.type = type;
  }
}

