// Reimplementation of jsonschema's TypeChecker (Draft 7) based on its
// observable interface behavior: is_type(instance, type).

import { UndefinedTypeCheck } from './exceptions.mjs';

function isArray(checker, instance) {
  return Array.isArray(instance);
}

function isBoolean(checker, instance) {
  return typeof instance === 'boolean';
}

function isInteger(checker, instance) {
  // Python: isinstance(instance, int) but not bool
  return typeof instance === 'number' && Number.isInteger(instance);
}

function isNull(checker, instance) {
  return instance === null;
}

function isNumber(checker, instance) {
  // Python: isinstance(instance, (int, float)) but not bool
  return typeof instance === 'number';
}

function isObject(checker, instance) {
  return typeof instance === 'object' && instance !== null && !Array.isArray(instance);
}

function isString(checker, instance) {
  return typeof instance === 'string';
}

export class TypeChecker {
  constructor(definitions) {
    this._typeCheckers = new Map(Object.entries(definitions));
  }

  is_type(instance, type) {
    if (!this._typeCheckers.has(type)) {
      throw new UndefinedTypeCheck(type);
    }
    const fn = this._typeCheckers.get(type);
    return fn(this, instance);
  }
}

export const draft7TypeChecker = new TypeChecker({
  array: isArray,
  boolean: isBoolean,
  integer: isInteger,
  null: isNull,
  number: isNumber,
  object: isObject,
  string: isString,
});

