// Reimplementation of jsonschema.Draft7Validator limited to the interface
// surface used by the source script: construction with a schema and the
// TYPE_CHECKER attribute.

import { draft7TypeChecker } from './types.mjs';

export class Draft7Validator {
  constructor(schema) {
    this.schema = schema;
  }

  // TYPE_CHECKER is a class-level attribute in jsonschema; every instance
  // exposes the same shared type checker.
  get TYPE_CHECKER() {
    return draft7TypeChecker;
  }
}

Draft7Validator.TYPE_CHECKER = draft7TypeChecker;

