// Minimal reimplementation of Python's argparse, restricted to the behavior
// observable in the source script: long options with values, -h/--help,
// required arguments, and argparse-compatible usage/error output.

import { basename } from 'node:path';

export class ArgumentParser {
  constructor() {
    this.prog = basename(process.argv[1] || 'test8.mjs');
    this._options = []; // {flags, dest, metavar, required, help, isHelp}
  }

  add_argument(flag, { required = false, help = '' } = {}) {
    const dest = flag.replace(/^--?/, '');
    const metavar = dest.toUpperCase();
    this._options.push({ flags: [flag], dest, metavar, required, help, isHelp: false });
  }

  _allOptions() {
    return [
      { flags: ['-h', '--help'], dest: 'help', metavar: null, required: false, help: 'show this help message and exit', isHelp: true },
      ...this._options,
    ];
  }

  _formatUsage() {
    const parts = ['[-h]'];
    for (const opt of this._options) {
      parts.push(`${opt.flags[0]} ${opt.metavar}`);
    }
    return `usage: ${this.prog} ${parts.join(' ')}`;
  }

  _formatHelp() {
    const lines = [this._formatUsage(), '', 'options:'];
    const entries = [];
    for (const opt of this._allOptions()) {
      const invocation = opt.isHelp
        ? '-h, --help'
        : `${opt.flags[0]} ${opt.metavar}`;
      entries.push([invocation, opt.help]);
    }
    const width = Math.max(...entries.map(([inv]) => inv.length));
    for (const [inv, help] of entries) {
      lines.push(`  ${inv.padEnd(width)}  ${help}`);
    }
    return lines.join('\n');
  }

  error(message) {
    process.stderr.write(this._formatUsage() + '\n');
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    process.exit(2);
  }

  _printHelpAndExit() {
    process.stdout.write(this._formatHelp() + '\n');
    process.exit(0);
  }

  _matchLong(name) {
    // Exact match or unambiguous prefix abbreviation, as argparse allows.
    const longs = this._allOptions().flatMap((o) => o.flags)
      .filter((f) => f.startsWith('--'));
    if (longs.includes(name)) return name;
    const matches = longs.filter((f) => f.startsWith(name));
    if (matches.length === 1) return matches[0];
    if (matches.length > 1) {
      this.error(`ambiguous option: ${name} could match ${matches.join(', ')}`);
    }
    return null;
  }

  _looksLikeOption(token) {
    // A token starting with '-' is treated as an option unless it is a
    // negative number (no option strings look like negative numbers here).
    if (token.length < 2 || token[0] !== '-') return false;
    return !/^-\d/.test(token) && token !== '-';
  }

  parse_args(argv = process.argv.slice(2)) {
    const values = {};
    for (const opt of this._options) values[opt.dest] = undefined;
    const extras = [];

    for (let i = 0; i < argv.length; i++) {
      const token = argv[i];
      let name = token;
      let inlineValue;
      const eq = token.indexOf('=');
      if (token.startsWith('--') && eq !== -1) {
        name = token.slice(0, eq);
        inlineValue = token.slice(eq + 1);
      }

      if (token === '-h' || token === '--help') {
        this._printHelpAndExit();
      }

      if (name.startsWith('--')) {
        const matched = this._matchLong(name);
        if (matched === '--help') this._printHelpAndExit();
        const opt = matched
          ? this._options.find((o) => o.flags.includes(matched))
          : null;
        if (!opt) {
          extras.push(token);
          continue;
        }
        if (inlineValue !== undefined) {
          values[opt.dest] = inlineValue;
        } else {
          const next = argv[i + 1];
          if (next === undefined || this._looksLikeOption(next)) {
            this.error(`argument ${opt.flags[0]}: expected one argument`);
          }
          values[opt.dest] = next;
          i++;
        }
      } else {
        extras.push(token);
      }
    }

    const missing = this._options
      .filter((o) => o.required && values[o.dest] === undefined)
      .map((o) => o.flags[0]);
    if (missing.length > 0) {
      this.error(`the following arguments are required: ${missing.join(', ')}`);
    }
    if (extras.length > 0) {
      this.error(`unrecognized arguments: ${extras.join(' ')}`);
    }

    return values;
  }
}

