import { ArgumentParser } from './lib/cli/argparse.mjs';
import { Draft7Validator } from './lib/jsonschema/validators.mjs';
import { UndefinedTypeCheck } from './lib/jsonschema/exceptions.mjs';

const parser = new ArgumentParser();
parser.add_argument('--a', { required: true, help: 'schema (JSON string)' });
parser.add_argument('--b', { required: true, help: 'type name' });
const args = parser.parse_args();

let schema;
try {
  schema = JSON.parse(args.a);
} catch (err) {
  // Mirrors Python's unhandled json.JSONDecodeError: traceback on stderr,
  // exit code 1.
  process.stderr.write(`json.decoder.JSONDecodeError: ${err.message}\n`);
  process.exit(1);
}

const validator = new Draft7Validator(schema); // Create validator
const typeChecker = validator.TYPE_CHECKER; // Get type checker
let result;
try {
  result = typeChecker.is_type(args.b, args.b); // Check if type exists
} catch (err) {
  if (err instanceof UndefinedTypeCheck) {
    process.stderr.write(`jsonschema.exceptions.UndefinedTypeCheck: ${err.message}\n`);
    process.exit(1);
  }
  throw err;
}
console.log(result ? 'True' : 'False');

